use std::{rc::Rc as LocalRc,cell::RefCell as LocalCell,io::Write,panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Clone)]struct Bytes(LocalRc<LocalCell<Vec<u8>>>);impl Write for Bytes{fn write(&mut self,b:&[u8])->std::io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn result(f:impl FnOnce())->String{match catch_unwind(AssertUnwindSafe(f)){Ok(())=>"ok".into(),Err(e)=>{let text=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");if text.contains("NullPointerException"){"NullPointerException".into()}else if text.contains("StringIndexOutOfBoundsException"){"StringIndexOutOfBoundsException".into()}else{format!("panic: {text}")}}}}
fn output(mut f:impl FnMut(&mut dyn XmlWriter))->Value{let mut m=MemoryXmlWriter::new();let mr=result(||f(&mut m));let units=m.getCodeUnits().iter().map(|v|format!("{v:04x}")).collect::<String>();let bytes=Bytes(LocalRc::new(LocalCell::new(vec![])));let mut b=BufferXmlWriter::new(Box::new(bytes.clone()));let br=result(||{f(&mut b);b.flush();});json!({"memoryResult":mr,"units":units,"bufferResult":br,"bytes":base64(&bytes.0.borrow())})}
fn border(p:&Value)->Option<Rc<RefCell<BorderFormatting>>>{if p["null"]==true{return None;}let mut b=BorderFormatting::BorderFormatting();if p["default"]==true{return Some(Rc::new(RefCell::new(b)));}let s=p["style"].as_i64().unwrap()as i32;let c=p["color"].as_i64().unwrap()as i32;b.setBorderLeft(s);b.setBorderRight(s+1);b.setBorderTop(s+2);b.setBorderBottom(s+3);b.setBorderDiagonal(s+4);b.setLeftBorderColor(c);b.setRightBorderColor(c);b.setTopBorderColor(c);b.setBottomBorderColor(c);b.setDiagonalBorderColor(c);b.setForwardDiagonalOn(p["forward"].as_bool().unwrap());b.setBackwardDiagonalOn(p["backward"].as_bool().unwrap());if p["internal"].as_bool().unwrap(){b.setBorderVertical(s);b.setBorderHorizontal(s+1);b.setVerticalBorderColor(c);b.setHorizontalBorderColor(c);}Some(Rc::new(RefCell::new(b)))}
fn options()->Value{let mut out=vec![];for bits in 0..64{let mut b=BorderFormatting::BorderFormatting();if bits&1!=0{b.setLeftOption();}if bits&2!=0{b.setRightOption();}if bits&4!=0{b.setTopOption();}if bits&8!=0{b.setBottomOption();}if bits&16!=0{b.setVerticalOption();}if bits&32!=0{b.setHorizontalOption();}let c=b.clone();out.push(json!([c.hasLeft(),c.hasRight(),c.hasTop(),c.hasBottom(),c.hasVertical(),c.hasHorizontal()]));}json!(out)}
fn history(input:&Value)->Value{let mut label=BordersLabel::BordersLabel();let b=border(&input["borders"][5]).unwrap();let mut out=vec![];for i in 0..15{if i==12{label=BordersLabel::BordersLabel();}let value=if [9,10,12,13].contains(&i){None}else if i%3==0{Some(b.clone())}else{Some(Rc::new(RefCell::new(b.borrow().clone())))};let mut id=None;let r=result(||id=Some(label.addForWriter(value)));let mut row=json!({"result":r});if let Some(id)=id{row["id"]=json!(id);}if i==5{b.borrow_mut().setLeftBorderColor(-16711936);}row["output"]=output(|w|label.write(w));out.push(row);}json!(out)}
fn palettes(input:&Value)->Value{let book=KmoBook::KmoBook();let palette=book.getPalette();let label=ColorsLabel::ColorsLabel(&book);let mut out=vec![output(|w|label.write(w))];palette.setIsPaletteMod(true);out.push(output(|w|label.write(w)));book.setPalette(Rc::new(KmoPalette::new()));out.push(output(|w|label.write(w)));for (i,c)in input["paletteColors"].as_array().unwrap().iter().enumerate(){let color=c.as_i64().unwrap()as i32;palette.setColorAtIndex(8+i as i16,(color>>16)as i8,(color>>8)as i8,color as i8);out.push(output(|w|label.write(w)));}palette.setIsPaletteMod(false);out.push(output(|w|label.write(w)));json!(out)}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
