fn original_android_border_options_aliases_and_palette_writer(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/border-colors-r0b38");let java:Value=serde_json::from_slice(&std::fs::read(root.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(root.join("inputs.json")).unwrap()).unwrap();let borders:Vec<_>=input["borders"].as_array().unwrap().iter().map(|p|{let b=border(p);output(|w|BordersLabel::writeBorder(w,b.as_ref().map(|b|b.borrow()).as_deref()))}).collect();let mut types:Vec<_>=(i16::MIN..=i16::MAX).map(|v|json!(BordersLabel::getStyle(Some(v)))).collect();types.push(json!(result(||{BordersLabel::getStyle(None);})));let native=json!({"borders":borders,"types":types,"options":options(),"history":history(&input),"palettes":palettes(&input)});std::fs::write(root.join("rust.json"),serde_json::to_vec_pretty(&native).unwrap()).unwrap();compare(&native,&java,"root");}
